import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"42. 文件指针和 fopen / fclose","description":"The Little Book of C 中文版 — 42. 文件指针和 fopen / fclose","frontmatter":{"title":"42. 文件指针和 fopen / fclose","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","05-输入输出与文件","中文"],"description":"The Little Book of C 中文版 — 42. 文件指针和 fopen / fclose","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":42,"sidebarWeight":42,"alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/042-File Pointers and fopen fclose","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/042-File Pointers and fopen fclose"},"headers":[],"relativePath":"posts/c教程/zh-CN/05-输入输出与文件/042-File Pointers and fopen fclose.md","filePath":"posts/c教程/zh-CN/05-输入输出与文件/042-File Pointers and fopen fclose.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/05-输入输出与文件/042-File Pointers and fopen fclose.md"};function o(i,a,l,c,d,r){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/05-Input Output and Files/042-File Pointers and fopen fclose)</p><p>文件让你的 C 程序记住运行时之外的事情。与程序结束时消失的标准输入和输出不同，文件提供持久存储，您可以在运行之间读取和写入数据。</p><p>本节介绍 C 语言中的关键文件处理 API：<code>fopen()</code>,<code>fclose()</code>,<code>fprintf()</code>,<code>fscanf()</code>，以及他们的亲戚。</p><h4 id="大局观" tabindex="-1">大局观 <a class="header-anchor" href="#大局观" aria-label="Permalink to &quot;大局观&quot;">​</a></h4><p>C 中的文件 I/O 使用<code>FILE *</code>代表一个打开的文件的指针。您不直接操作磁盘，而是通过运行时管理的缓冲文件流进行读写。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE *fp = fopen(&quot;data.txt&quot;, &quot;r&quot;);</span></span></code></pre></div><p>这将返回一个指向<code>FILE</code>如果成功则反对，或者<code>NULL</code>如果文件无法打开。</p><h4 id="文件模式" tabindex="-1">文件模式 <a class="header-anchor" href="#文件模式" aria-label="Permalink to &quot;文件模式&quot;">​</a></h4><p>打开文件时，您指定一种模式，即您打算用它做什么。</p><table tabindex="0"><thead><tr><th>模式</th><th>意义</th><th>行为</th></tr></thead><tbody><tr><td><code>&quot;r&quot;</code></td><td>阅读</td><td>如果文件不存在则失败</td></tr><tr><td><code>&quot;w&quot;</code></td><td>写</td><td>创建新的或截断现有的</td></tr><tr><td><code>&quot;a&quot;</code></td><td>附加</td><td>打开或创建；写到最后</td></tr><tr><td><code>&quot;r+&quot;</code></td><td>读/写</td><td>必须存在</td></tr><tr><td><code>&quot;w+&quot;</code></td><td>读/写</td><td>如果存在则截断</td></tr><tr><td><code>&quot;a+&quot;</code></td><td>读/写</td><td>追加；阅读从头开始</td></tr></tbody></table><h4 id="小代码-写入和读取文件" tabindex="-1">小代码：写入和读取文件 <a class="header-anchor" href="#小代码-写入和读取文件" aria-label="Permalink to &quot;小代码：写入和读取文件&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;example.txt&quot;, &quot;w&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Failed to open file&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    fprintf(fp, &quot;Hello, file world!\\n&quot;);</span></span>
<span class="line"><span>    fprintf(fp, &quot;C makes you closer to the machine.\\n&quot;);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    fp = fopen(&quot;example.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Failed to reopen file&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char line[100];</span></span>
<span class="line"><span>    printf(&quot;--- File Content ---\\n&quot;);</span></span>
<span class="line"><span>    while (fgets(line, sizeof(line), fp))</span></span>
<span class="line"><span>        printf(&quot;%s&quot;, line);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--- File Content ---</span></span>
<span class="line"><span>Hello, file world!</span></span>
<span class="line"><span>C makes you closer to the machine.</span></span></code></pre></div><h4 id="它是如何运作的" tabindex="-1">它是如何运作的 <a class="header-anchor" href="#它是如何运作的" aria-label="Permalink to &quot;它是如何运作的&quot;">​</a></h4><p>1.<code>fopen()</code>创建与文件的连接。 2.<code>fprintf()</code>写入格式化文本，就像<code>printf()</code>但对于文件流。 3.<code>fclose()</code>刷新缓冲区并关闭文件。 4. 重新打开<code>&quot;r&quot;</code>模式来阅读您所写的内容。</p><p>您还可以与<code>fscanf()</code>读取格式化数据。</p><h4 id="检查错误" tabindex="-1">检查错误 <a class="header-anchor" href="#检查错误" aria-label="Permalink to &quot;检查错误&quot;">​</a></h4><p>始终检查文件操作是否有错误。使用<code>if (!fp)</code>后<code>fopen()</code>，并使用<code>perror()</code>打印原因。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE *f = fopen(&quot;missing.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>if (!f) {</span></span>
<span class="line"><span>    perror(&quot;Error opening file&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error opening file: No such file or directory</span></span></code></pre></div><h4 id="使用-fscanf-读取格式化数据" tabindex="-1">使用 fscanf 读取格式化数据 <a class="header-anchor" href="#使用-fscanf-读取格式化数据" aria-label="Permalink to &quot;使用 fscanf 读取格式化数据&quot;">​</a></h4><p>您可以使用解析文本文件<code>fscanf()</code>，就像<code>scanf()</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;numbers.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) return 1;</span></span>
<span class="line"><span>    int a, b;</span></span>
<span class="line"><span>    while (fscanf(fp, &quot;%d %d&quot;, &amp;a, &amp;b) == 2)</span></span>
<span class="line"><span>        printf(&quot;%d + %d = %d\\n&quot;, a, b, a + b);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果<code>numbers.txt</code>包含：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2 3</span></span>
<span class="line"><span>10 15</span></span>
<span class="line"><span>7 9</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2 + 3 = 5</span></span>
<span class="line"><span>10 + 15 = 25</span></span>
<span class="line"><span>7 + 9 = 16</span></span></code></pre></div><h4 id="文件位置和倒带" tabindex="-1">文件位置和倒带 <a class="header-anchor" href="#文件位置和倒带" aria-label="Permalink to &quot;文件位置和倒带&quot;">​</a></h4><p>您可以使用以下方法移动文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fseek(fp, 0, SEEK_SET);  // go to beginning</span></span>
<span class="line"><span>fseek(fp, 0, SEEK_END);  // go to end</span></span>
<span class="line"><span>rewind(fp);              // reset to start</span></span></code></pre></div><p>要知道你在哪里：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>long pos = ftell(fp);</span></span>
<span class="line"><span>printf(&quot;Current position: %ld\\n&quot;, pos);</span></span></code></pre></div><h4 id="写入二进制数据" tabindex="-1">写入二进制数据 <a class="header-anchor" href="#写入二进制数据" aria-label="Permalink to &quot;写入二进制数据&quot;">​</a></h4><p>文本文件是人类可读的；二进制文件存储原始字节。你将使用<code>fwrite()</code>和<code>fread()</code>为此（下一节将详细介绍）。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int numbers[] = {1, 2, 3, 4};</span></span>
<span class="line"><span>fwrite(numbers, sizeof(int), 4, fp);</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>文件 I/O 是 C 程序和现实世界之间的桥梁：</p><ul><li>配置和日志文件</li><li>数据库存储</li><li>缓存和序列化</li><li>操作系统实用程序（复制、移动、grep 等）</li></ul><p>它总是教导资源管理<code>fopen()</code>和<code>fclose()</code>两人一组，检查错误，并优雅地处理故障。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个程序，询问您的姓名并将其保存到<code>user.txt</code>.</li><li>每次程序运行时附加时间戳。</li><li>读取所有行并计算程序已执行的次数。</li><li>修改示例以反转从文件读取的所有行。</li><li>使用优雅地处理丢失的文件<code>perror()</code>.</li></ol><p>您现在知道如何安全地打开、读取和写入文本文件。接下来，您将深入了解二进制文件，其中数据以原始字节移动，非常适合高效存储结构和数组。</p>`,45)])])}const f=s(t,[["render",o]]);export{h as __pageData,f as default};
